use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut path = input.to_string();
    let mut last_component = None;

    while let Some(segment) = path.split('/').next() {
        if segment == ".." {
            if let Some(last) = last_component {
                path = format!("{}/{}", last, segment);
            } else {
                path = format!("..{}", segment);
            }
        } else {
            last_component = Some(segment);
        }
    }

    if last_component.is_none() {
        path
    } else {
        path
    }
}
